fn frame(t: i32) {
    host::display::clear(0x0c1016);
    if host::display::state_get(0) == 0 {
        host::mp::auto(4);
        host::display::state_set(0, 1);
    }
    let palette = [0xffcc33, 0x33ff88, 0x66aaff, 0xff6688, 0xcc99ff, 0xffaa55, 0x55dddd, 0xdddddd];
    let cell: i32 = 48;
    let ox: i32 = 64;
    let oy: i32 = 64;
    let mut gy: i32 = 0;
    while gy < 8 {
        let mut gx: i32 = 0;
        while gx < 8 {
            host::display::fill_rect(ox + gx * cell + 1, oy + gy * cell + 1, cell - 2, cell - 2, 0x1a2028);
            gx = gx + 1;
        }
        gy = gy + 1;
    }
    if host::mp::connected() == 0 {
        host::display::draw_string(150, 20, "CONNECTING...", 0x8899aa, 2);
    } else {
        let me: i32 = host::mp::self_index();
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let mut cx: i32 = (px - ox) / cell;
        let mut cy: i32 = (py - oy) / cell;
        if cx < 0 {
            cx = 0;
        }
        if cx > 7 {
            cx = 7;
        }
        if cy < 0 {
            cy = 0;
        }
        if cy > 7 {
            cy = 7;
        }
        host::mp::set(0, cy * 8 + cx + 1);
        let n: i32 = host::mp::peer_count();
        let mut i: i32 = 0;
        while i < n {
            let packed: i32 = host::mp::get(i, 0);
            if packed > 0 {
                let pc: i32 = packed - 1;
                let hx: i32 = ox + (pc % 8) * cell;
                let hy: i32 = oy + (pc / 8) * cell;
                host::display::fill_rect(hx + 4, hy + 4, cell - 8, cell - 8, palette[i]);
                host::display::draw_number(hx + cell / 2 - 3, hy + cell / 2 - 4, i, 0x000000, 1);
            }
            i = i + 1;
        }
        host::display::draw_string(64, 20, "STAND ON A CELL TO CLAIM IT", 0x8899aa, 1);
        host::display::draw_string(64, 480, "PEERS", 0x8899aa, 1);
        host::display::draw_number(112, 478, n, 0xffffff, 1);
    }
    host::display::present();
}
